<?php
defined('ABSPATH')||exit; final class Azula_Analytics_Date_Range{
private const P=['today','yesterday','last_7_days','last_30_days','this_month','custom'];private const C=['none','previous_period','previous_year'];
public static function from_request(array $r):array{$p=isset($r['range'])?sanitize_key(wp_unslash($r['range'])):'today';$c=isset($r['compare'])?sanitize_key(wp_unslash($r['compare'])):'none';if(!in_array($p,self::P,true))$p='today';if(!in_array($c,self::C,true))$c='none';$tz=wp_timezone();$t=new DateTimeImmutable('today',$tz);if($p==='yesterday'){$s=$t->modify('-1 day');$e=$s;}elseif($p==='last_7_days'){$s=$t->modify('-6 days');$e=$t;}elseif($p==='last_30_days'){$s=$t->modify('-29 days');$e=$t;}elseif($p==='this_month'){$s=$t->modify('first day of this month');$e=$t;}elseif($p==='custom'){$s=self::parse($r['date_from']??'',$tz)?:$t;$e=self::parse($r['date_to']??'',$tz)?:$s;if($e<$s)[$s,$e]=[$e,$s];}else{$s=$t;$e=$t;}$x=self::norm($s,$e);$x['preset']=$p;$x['comparison']=$c;$x['compare_range']=self::cmp($x,$c);return$x;}
private static function parse(string $v,DateTimeZone $tz):?DateTimeImmutable{$d=DateTimeImmutable::createFromFormat('!Y-m-d',sanitize_text_field(wp_unslash($v)),$tz);return$d?:null;}
private static function norm(DateTimeImmutable $s,DateTimeImmutable $e):array{$s=$s->setTime(0,0,0);$e=$e->setTime(23,59,59);return['start'=>$s,'end'=>$e,'start_sql'=>$s->format('Y-m-d H:i:s'),'end_sql'=>$e->format('Y-m-d H:i:s'),'date_from'=>$s->format('Y-m-d'),'date_to'=>$e->format('Y-m-d'),'days'=>(int)$s->diff($e)->format('%a')+1];}
private static function cmp(array $r,string $m):?array{if($m==='none')return null;if($m==='previous_year')return self::norm($r['start']->modify('-1 year'),$r['end']->modify('-1 year'));$e=$r['start']->modify('-1 second');return self::norm($e->modify('-'.($r['days']-1).' days')->setTime(0,0,0),$e);}
}